import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]
    a.sort()

    total = n * (n - 1) * (n - 2) // 6
    bad = 0

    for k in range(2, n):
        x = a[k]
        i = 0
        j = k - 1

        while i < j:
            if a[i] + a[j] <= x:
                bad += j - i
                i += 1
            else:
                j -= 1

    print(total - bad)

if __name__ == "__main__":
    main()
